#include <cstdio>
#include <vector>
using namespace std;

int n, q;
vector<long long> fenwick;
vector<int> a;

void update(int i, int delta) {
    for (; i <= n; i += i & (-i))
        fenwick[i] += delta;
}

long long query(int i) {
    long long s = 0;
    for (; i > 0; i -= i & (-i))
        s += fenwick[i];
    return s;
}

int main() {
    scanf("%d %d", &n, &q);
    fenwick.assign(n + 1, 0);
    a.assign(n + 1, 0);

    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        update(i, a[i]);
    }

    for (int i = 0; i < q; i++) {
        int t;
        scanf("%d", &t);
        if (t == 0) {
            int k, p;
            scanf("%d %d", &k, &p);
            update(k, p - a[k]);
            a[k] = p;
        } else {
            int k;
            scanf("%d", &k);
            printf("%lld\n", query(k));
        }
    }
    return 0;
}
